export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { SaveEngineeringDataSchema } from '@/lib/validation/apiSchemas'
import { requireProjectOwnership, requireProjectReadAccess } from '@/lib/auth/ownership'
import { AuthenticationError, AuthorizationError, ConflictError, NotFoundError } from '@/lib/api/errors'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface EngineeringSurveyDataRow {
  id: string
  project_id: string
  alignment_id: string | null
  station_chainage: number | null
  ground_level: number | null
  design_level: number | null
  cut_depth: number | null
  fill_depth: number | null
  cross_section: unknown | null
  metadata: unknown | null
  subtype: string | null
  data: Record<string, unknown>
  created_at: Date
  updated_at: Date
}

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  if (!ctx.userId || ctx.userId === 'anonymous') throw new AuthenticationError()
  const { searchParams } = new URL(req.url)
  const parsed = z.string().guid().safeParse(searchParams.get('projectId'))
  if (!parsed.success) return NextResponse.json({ error: 'A valid projectId is required' }, { status: 400 })
  const projectId = parsed.data.toLowerCase()
  const access = await requireProjectReadAccess(projectId, ctx.userId)
  if (!access.ok) {
    if (!access.error) throw new AuthorizationError('Project read access could not be verified.')
    return access.error
  }
  if (!access.projectUserId) throw new AuthorizationError('Recorded project ownership is required.')
  // One MVCC snapshot binds payload and owner. A read-only member needs no
  // UPDATE/row-lock privilege; a transferred project cannot expose its payload.
  const { rows } = await db.query<{ project_owner: string | null; payload: EngineeringSurveyDataRow | null }>(
    `SELECT project.user_id AS project_owner, to_jsonb(payload) AS payload
       FROM projects project
       LEFT JOIN engineering_survey_data payload
         ON payload.project_id = project.id AND project.user_id = $2
      WHERE project.id = $1 LIMIT 2`, [projectId, access.projectUserId])
  if (!rows.length) throw new NotFoundError('Project no longer exists.')
  if (rows[0].project_owner !== access.projectUserId) throw new AuthorizationError('Project ownership changed; refresh before reading.')
  if (rows.length !== 1) throw new ConflictError('Multiple engineering payloads require review before reading.')
  return NextResponse.json({ data: rows[0].payload }, { headers: { 'Cache-Control': 'private, no-store' } })
})

export const POST = apiHandler({ auth: true, schema: SaveEngineeringDataSchema, rateLimit: { max: 60, windowMs: 60000 } }, async (_req, ctx) => {
  if (!ctx.userId || ctx.userId === 'anonymous') throw new AuthenticationError()
  const { projectId, subtype, data } = ctx.body as z.infer<typeof SaveEngineeringDataSchema>
  const access = await requireProjectOwnership(projectId, ctx.userId)
  if (!access.ok) {
    if (!access.error) throw new AuthorizationError('Project write access could not be verified.')
    return access.error
  }
  const saved = await db.transaction(async client => {
    const { rows: projects } = await client.query<{ user_id: string | null }>(
      'SELECT user_id FROM projects WHERE id = $1 FOR SHARE', [projectId])
    if (!projects.length) throw new NotFoundError('Project no longer exists.')
    if (projects[0].user_id !== ctx.userId) throw new AuthorizationError('Project ownership changed; refresh before saving.')
    const { rows } = await client.query<EngineeringSurveyDataRow>(
      `INSERT INTO engineering_survey_data (project_id, subtype, data)
       VALUES ($1, $2, $3::jsonb)
       ON CONFLICT (project_id) DO UPDATE SET subtype = EXCLUDED.subtype,
         data = EXCLUDED.data, updated_at = NOW()
       RETURNING *`, [projectId, subtype, JSON.stringify(data)])
    if (rows.length !== 1 || !rows[0].id || rows[0].project_id !== projectId) throw new Error('Engineering data persistence was not confirmed.')
    return rows[0]
  })
  return NextResponse.json({ data: saved }, { headers: { 'Cache-Control': 'private, no-store' } })
})
